-- 1812 (2026-11-24): the engine's behaviours, in the database — the taxonomy and the engine as ONE system.
--
-- Owner 11/24: "this is what engine would select from right? the engine doesn't have extra
-- stuff lol we are not aware of?" · "we need both in sync 1 system all concepts" · "we need
-- them synced taxonomy and engine. also the taxonomy page should show the db entry and the
-- c++ class should be viewable with hyperlink to parent classes" · "this is a holistic
-- system that feeds off each other".
--
-- Until today the link between the 189 catalogue concepts and the engine was six rows
-- (game_engine_acts).  A full read of the engine's decision code (game/src/ai, 11/24) found
-- 156 distinct behaviours.  This migration records every one, with its place in the code and
-- one of three standings:
--
--   concept   a catalogue concept names it (concept_id; other_concepts = also fits)
--   unnamed   real football the catalogue has no row for (suggested = a name to consider;
--             other_concepts = the nearest existing rows)
--   fudge     a mechanical patch with no football meaning (anti-flicker, clamps)
--
-- is_read marks a RECOGNITION — something a player or the team reads (who wins the race,
-- is the pass safe, which phase) — as opposed to something he does.  The mappings are a
-- first pass (confidence says how sure); the owner settles the unnamed ones.
--
-- The rule this table makes checkable: a behaviour with no concept row is a visible gap,
-- and a concept with no behaviour is knowledge the engine does not act on yet.
--
-- game_engine_sources / game_engine_classes hold the C++ itself for the page — filled and
-- refreshed by scripts/taxonomy/export_engine_index.py (the backend image has no source),
-- which also sets each behaviour's symbol / class_name.

CREATE TABLE IF NOT EXISTS game_engine_behaviours (
    code           text PRIMARY KEY,
    file           text NOT NULL,
    line           integer NOT NULL,
    symbol         text,                       -- Class::method the line sits in (export script)
    class_name     text,                       -- its class, when that is a real class
    tag            text,                       -- the design slice, e.g. G5.82 §8.183
    who            text NOT NULL CHECK (who IN ('individual', 'group', 'team', 'keeper')),
    what           text NOT NULL,
    status         text NOT NULL CHECK (status IN ('concept', 'unnamed', 'fudge')),
    concept_id     smallint REFERENCES game_concepts(id),
    other_concepts text,
    suggested      text,
    confidence     text CHECK (confidence IN ('high', 'medium', 'low')),
    is_read        boolean NOT NULL DEFAULT false
);
CREATE INDEX IF NOT EXISTS game_engine_behaviours_concept_idx ON game_engine_behaviours (concept_id);

CREATE TABLE IF NOT EXISTS game_engine_sources (
    file        text PRIMARY KEY,
    commit      text NOT NULL,
    line_count  integer NOT NULL,
    body        text NOT NULL,
    exported_at timestamptz NOT NULL DEFAULT now()
);
CREATE TABLE IF NOT EXISTS game_engine_classes (
    name       text NOT NULL,
    file       text NOT NULL,
    line_start integer NOT NULL,
    line_end   integer NOT NULL,
    parent     text,
    doc        text,
    kind       text NOT NULL,
    PRIMARY KEY (name, file)
);

ON CONFLICT (code) DO NOTHING;
