INSERT INTO game_engine_behaviours (code, file, line, tag, who, what, status, concept_id, other_concepts, suggested, confidence, is_read) VALUES
  ('block_spot', 'game/src/ai/DefendingBlock.cpp', 421, 'G5.21 §8.119; G5.42 §8.142', 'team', 'Every man without another job stands at his role''s real depth off our line for the ball''s depth band (DFL table by role x 10 m band), so the lines stay stacked behind the ball.', 'concept', (SELECT id FROM game_concepts WHERE name = 'compact-block'), NULL, NULL, 'high', false),
  ('block_width_narrow', 'game/src/ai/Brain.cpp', 227, 'G5.38 §8.138', 'team', 'Each role keeps only a share of its formation width, by the ball''s band - the block narrows as the ball nears our goal (full-backs half their width apart inside 20 m).', 'concept', (SELECT id FROM game_concepts WHERE name = 'compact-block'), 'close-the-centre', NULL, 'medium', false),
  ('block_slide_across', 'game/src/ai/Brain.cpp', 205, 'G5.7', 'team', 'The block''s lateral spots shift toward the ball''s side by a fraction of the ball''s y, capped (physics.shape.theirs_shift_y / theirs_cap_y_m; no row = no slide).', 'concept', (SELECT id FROM game_concepts WHERE name = 'block-slide'), 'balance', NULL, 'medium', false),
  ('block_shift_while_ball_travels', 'game/src/ai/Brain.cpp', 253, 'G5.30 §8.128; G5.162 §8.267', 'team', 'The block shifts across to where a free ball will first be taken while it is still travelling, not after it lands (depth alone reads the ball where it is since depth_now, so the lines trail a moving ball as real ones do).', 'unnamed', NULL, 'block-slide', 'shift-while-the-ball-travels', 'medium', false),
  ('block_tracks_carrier', 'game/src/ai/Brain.cpp', 866, 'G5.30 §8.128', 'team', 'Holding the block while their man carries the ball, each man runs with his spot''s own velocity (the spot 0.2 s on along the carrier''s run) and closes the gap on top - the block drops/moves in phase with the carrier instead of trailing him.', 'unnamed', NULL, 'block-slide, delay', 'block-moves-with-the-carrier', 'low', false),
  ('block_height_per_spell', 'game/src/ai/DefendingBlock.cpp', 434, 'G5.52 §8.153', 'team', 'The whole block''s height is set once per opposition spell (a draw through the real p10-p90 spell offsets, -5.6 to +5.4 m), faded out inside 18 m of our line.', 'concept', (SELECT id FROM game_concepts WHERE name = 'block-height'), 'engage-line', NULL, 'medium', false),
  ('block_forward_offset_per_spell', 'game/src/ai/DefendingBlock.cpp', 450, 'G5.70 §8.171', 'individual', 'Each forward (AM / wide / ST) takes his own depth offset off his role spot once per opposition spell; with the ball inside 15-25 m of our goal the spread widens - one stays up, another drops in. Defenders get none.', 'unnamed', NULL, 'outlet, anticipate-regain', 'forward-stays-up-or-drops-in', 'low', false),
  ('block_step_up_deep_wide', 'game/src/ai/DefendingBlock.cpp', 459, 'G5.219 §8.325', 'team', 'Their ball deep in their own third (65-70 m+ off our line) and by a touchline: the block''s spots step up by role (rows physics.block.wide_up_<role>; no row = 0).', 'concept', (SELECT id FROM game_concepts WHERE name = 'push-up'), 'touchline-trap', NULL, 'medium', false),
  ('block_squeeze_deep_wide', 'game/src/ai/DefendingBlock.cpp', 472, 'G5.221 §8.327', 'team', 'While their ball stays deep and wide the lines keep climbing at a per-role m/s for up to squeeze_max_s (7 s) (rows physics.block.squeeze_<role>; no row = 0).', 'concept', (SELECT id FROM game_concepts WHERE name = 'push-up'), 'call-squeeze', NULL, 'medium', false),
  ('block_cover', 'game/src/ai/DefendingBlock.cpp', 394, 'G5.41 §8.141', 'group', 'With exactly two centre-backs, the one nearer their most advanced outfielder is the deeper of the pair (half the real ~2.8 m depth gap below the CB spot), his partner the same above it; held until the other is switch_m nearer. Trainer label BlockCover (Brain.cpp:310).', 'concept', (SELECT id FROM game_concepts WHERE name = 'cover'), 'deep-sweeper', NULL, 'medium', false),
  ('block_goal_side_of_ball', 'game/src/ai/DefendingBlock.cpp', 483, 'G5.85 §8.186', 'individual', 'Ball within gs_r of our goal: a holder whose spot is near the ball slides straight toward the goal centre until he is between ball and goal. Built, ships OFF (gs_r 0).', 'unnamed', NULL, 'recover, block-shot-line', 'between-ball-and-goal', 'medium', false),
  ('def_into_the_lane', 'game/src/ai/Brain.cpp', 947, 'G5.197 §8.303', 'individual', 'Their carrier within lane_range_m (30 m) of our goal: a holder or marker goal-side of him and within lane_m of the ball-goal line steps onto that line (''get in line of the shot''). Off unless physics.block.lane_m has a row.', 'concept', (SELECT id FROM game_concepts WHERE name = 'block-shot-line'), NULL, NULL, 'high', false),
  ('press_ball', 'game/src/ai/DefendingBlock.cpp', 76, 'G5.21 §8.119; G5.25', 'individual', 'The one man who steps to their carrier stands a stand-off distance goal-side of him on his line to our goal (real nearest-defender p25/median/p75 by the ball''s five depth bands, one roll a spell), facing him.', 'concept', (SELECT id FROM game_concepts WHERE name = 'pressing-distance'), 'delay', NULL, 'high', false),
  ('press_pick_one_nearest', 'game/src/ai/DefendingBlock.cpp', 326, 'G5.21 §8.119', 'team', 'Exactly one presser: our nearest outfielder to the ball, kept until another is switch_m (2 m) nearer; nobody else leaves his job for the carrier.', 'concept', (SELECT id FROM game_concepts WHERE name = 'nearest-decides'), NULL, NULL, 'medium', false),
  ('press_tight_wide_loose_central', 'game/src/ai/DefendingBlock.cpp', 92, 'G5.218 §8.324', 'individual', 'Their ball 70 m+ off our line: the presser closes it tight by a touchline and stands off it in the middle (rows physics.press.stand_off_deep_{c,w}_*; no row = the band''s one distance).', 'unnamed', NULL, 'touchline-trap, engage-or-contain', 'close-it-wide-stand-off-central', 'medium', false),
  ('press_arrive_with_carrier', 'game/src/ai/Brain.cpp', 996, 'G5.39 §8.139', 'individual', 'The presser arrives at his stand-off spot no slower than their carrier is running, so he runs with him and stays goal-side instead of braking and trailing behind.', 'unnamed', NULL, 'drop-step, delay', 'run-with-the-carrier', 'medium', false),
  ('press_tackle_flat_clock', 'game/src/ai/DefendingBlock.cpp', 107, 'G5.147 §8.251', 'individual', 'In tackle reach and goal-side of the carrier, the presser dives in with a flat chance per second (0.75/s) - no read of whether the ball is exposed.', 'unnamed', NULL, 'tackle-timing, engage-or-contain', 'tackle-on-a-clock', 'low', false),
  ('def_press_on_pass', 'game/src/ai/DefendingBlock.cpp', 313, 'G5.82 §8.183', 'individual', 'Their pass in flight that their man will reach first: our nearest outfielder to the meet point steps out toward it (stand-off goal-side of that point, facing the ball) so he is on the receiver as it arrives.', 'unnamed', NULL, 'jump-the-pass, pressing-distance', 'press-as-the-pass-travels', 'low', false),
  ('def_hold_job_on_their_pass', 'game/src/ai/DefendingBlock.cpp', 266, 'G5.82 §8.183', 'team', 'Their pass, their man first to it by more than the margin: nobody of ours chases the ball - each keeps his mark or block spot (before, our first man ran down the line past their receiver).', 'unnamed', NULL, 'restraint', 'hold-your-job-on-their-pass', 'medium', false),
  ('def_cut_out_their_pass', 'game/src/ai/DefendingBlock.cpp', 271, 'G5.99 §8.200', 'individual', 'Their pass that our first man reaches before their receiver (by cut_margin ticks or more; default 0 = whenever first): he becomes the chaser and goes to take it.', 'concept', (SELECT id FROM game_concepts WHERE name = 'intercept'), 'jump-the-pass', NULL, 'medium', false),
  ('def_contest_high_ball', 'game/src/ai/DefendingBlock.cpp', 280, 'G5.71 §8.172; G5.151 §8.256; G5.152 §8.257; G5.153 §8.258', 'individual', 'Their ball in the air (0.3 m+ up) that their man meets first, or a close race for it: our nearest outfielder to that point goes there flat out, braked to arrive on the spot, to contest it in the air or be on him as it lands; it replaces the press-on-pass.', 'unnamed', NULL, 'win-duel, second-ball', 'contest-the-high-ball', 'medium', false),
  ('chase_ball', 'game/src/ai/DefendingBlock.cpp', 118, 'G5.21 §8.119', 'individual', 'A loose ball in play: our first man on the race read goes to the point where he can take it; if nobody can reach it inside the read''s horizon, or there is no read, our nearest outfielder goes (held with the switch_m margin).', 'concept', (SELECT id FROM game_concepts WHERE name = 'nearest-decides'), 'second-ball', NULL, 'high', false),
  ('recv_pass_is_his', 'game/src/ai/DefendingBlock.cpp', 261, 'G4.81', 'individual', 'Our own pass: the man it is for is the one who goes to meet it and the rest let it run - unless their man gets there first, when our first man on the race read goes too.', 'concept', (SELECT id FROM game_concepts WHERE name = 'meet-the-pass'), NULL, NULL, 'high', false),
  ('recv_always_meets', 'game/src/ai/Players.cpp', 63, 'G5.98 §8.199', 'individual', 'While our pass to him is loose he goes to meet it whether or not the race read has him first (the defender has to win it); before, a man read second walked back to his spot.', 'concept', (SELECT id FROM game_concepts WHERE name = 'meet-the-pass'), NULL, NULL, 'high', false),
  ('block_mark', 'game/src/ai/DefendingBlock.cpp', 133, 'G5.72 §8.173', 'individual', 'A marker stands goal-side of his man, mark_d metres off him on the man''s line to our goal''s centre.', 'concept', (SELECT id FROM game_concepts WHERE name = 'man-mark'), 'mark-position', NULL, 'high', false),
  ('mark_pickup_in_zone', 'game/src/ai/DefendingBlock.cpp', 342, 'G5.72 §8.173', 'group', 'Each CB / FB / DM (never the chaser, presser or contester; forwards do not mark) picks up their outfielder inside mark_r of his own block spot - nearest pair first, one marker a man, one man a marker, a pair already on kept a little further (hysteresis); their carrier is left to the presser.', 'concept', (SELECT id FROM game_concepts WHERE name = 'man-mark'), 'find-your-man', NULL, 'medium', false),
  ('mark_tighten_near_goal', 'game/src/ai/DefendingBlock.cpp', 202, 'G5.72 §8.173', 'individual', 'The marking distance shrinks and the pickup radius grows the nearer the attacker is to our goal (1.5 m off him inside 18 m, 4 m beyond 52 m).', 'concept', (SELECT id FROM game_concepts WHERE name = 'tighten-near-goal'), 'near-tight-far-zone', NULL, 'high', false),
  ('mark_run_with_man', 'game/src/ai/Brain.cpp', 860, 'G5.72 §8.173', 'individual', 'A marker moves with his man''s own velocity and closes the gap on top, so he runs with him rather than chasing where he was.', 'concept', (SELECT id FROM game_concepts WHERE name = 'track-the-runner'), NULL, NULL, 'medium', false),
  ('mark_see_man_and_ball', 'game/src/ai/DefendingBlock.cpp', 143, 'G5.72 §8.173', 'individual', 'While marking he faces the ball, goal-side of his man (''goal-side, see man and ball'').', 'concept', (SELECT id FROM game_concepts WHERE name = 'face-the-play'), NULL, NULL, 'high', false),
  ('hold_face_ball', 'game/src/ai/Brain.cpp', 348, NULL, 'individual', 'Settled within 2 m of his spot (holding shape, or the keeper in position) he turns to face the ball.', 'concept', (SELECT id FROM game_concepts WHERE name = 'face-the-play'), NULL, NULL, 'medium', false),
  ('block_recover', 'game/src/ai/Brain.cpp', 1040, 'G5.32 §8.130', 'individual', 'Without the ball, a man whose spot is a metre or more goal-side of him closes it quickly (shape_tau_back_s) - get goal-side first - while across and upfield he keeps the shift''s patience. Trainer label BlockRecover when the spot is recover_m (5 m)+ goal-side (Brain.cpp:309).', 'concept', (SELECT id FROM game_concepts WHERE name = 'recover'), 'chain-recover', NULL, 'high', false),
  ('def_danger_get_back', 'game/src/ai/Brain.cpp', 1018, 'G5.10 §8.108', 'team', 'Their ball inside shape_danger_m of our goal: the jog-and-ease limits come off and men get back into their shape at the defending pace (optionally a sprint, shape_danger_sprint).', 'concept', (SELECT id FROM game_concepts WHERE name = 'recover'), NULL, NULL, 'medium', false),
  ('read_in_danger', 'game/src/ai/Brain.cpp', 934, 'G5.10 §8.108', 'team', 'Reads ''we are in danger'': the ball is theirs (on it, or last touched) and inside shape_danger_m of our goal line.', 'unnamed', NULL, 'risk-by-third', 'read-danger-zone', 'medium', true),
  ('shape_shift_at_a_jog', 'game/src/ai/Brain.cpp', 1014, 'G5.5 §8.103', 'team', 'Adjusting his shape a man goes only as fast as the gap asks (gap / shape_tau_s): the team shifts as a block at a jog and accepts the lag.', 'unnamed', NULL, 'block-slide', 'shift-at-a-jog', 'medium', false),
  ('shape_pace_caps_by_direction', 'game/src/ai/Brain.cpp', 889, 'G5.31 §8.129; G5.95 §8.196', 'individual', 'Holding shape his speed is clamped by direction: across and up at shape_max, forward with our ball at the build-up jog (shift_fwd_max), back toward our goal at defend_max unless in danger - clamps fitted so the share of time over 5 m/s matches tracking.', 'fudge', NULL, NULL, NULL, 'medium', false),
  ('fwd_jog_back', 'game/src/ai/Brain.cpp', 903, 'G5.96 §8.197', 'individual', 'A forward (AM / wide / ST) holding shape drops back toward our goal at his own slower pace, even in danger - real forwards stay up as the ball goes past them.', 'unnamed', NULL, 'outlet, anticipate-regain', 'forwards-do-not-sprint-back', 'low', false),
  ('shape_moves_with_our_ball', 'game/src/ai/Brain.cpp', 1024, 'G5.14 §8.111', 'team', 'With our ball the shape closes on its spots quickly (shape_tau_ours_s) so the team moves up and across together with the ball instead of trailing 5-10 m deep.', 'unnamed', NULL, 'support, escape-and-advance', 'move-together-with-the-ball', 'medium', false),
  ('hold_walk_far_from_ball', 'game/src/ai/Brain.cpp', 1053, 'G5.137 §8.240; G5.138 §8.242; G5.174 §8.280', 'individual', 'With our ball not going forward, a man 15 m+ from the ball and not on a line run walks to his spot (1.5 m/s) rather than running with every step it takes; a full-back pushing on up his touchline is exempt.', 'unnamed', NULL, 'tempo-control', 'walk-when-the-ball-is-not-going-forward', 'low', false),
  ('line_run_pace', 'game/src/ai/Brain.cpp', 921, 'G5.94 §8.195', 'individual', 'With our ball, a holder within run_zone (12 m) of their offside line whose spot is ahead of him and on or within 4 m of that line is making a run: he goes at run pace and closes fast (run_tau) instead of shifting at a jog.', 'concept', (SELECT id FROM game_concepts WHERE name = 'runs'), NULL, NULL, 'medium', false),
  ('front_man_rides_the_line', 'game/src/ai/Brain.cpp', 855, 'G5.47 §8.147; G5.50 §8.150', 'individual', 'A front / second man whose spot hangs off their offside line moves with the line''s own velocity and, with the ball not going forward, closes a jumped spot at no more than front.close_mps (a walk or jog, not a sprint).', 'concept', (SELECT id FROM game_concepts WHERE name = 'stay-onside'), 'pin-the-fullback', NULL, 'low', false),
  ('read_our_ball_live', 'game/src/ai/Brain.cpp', 914, 'G5.95 §8.196', 'team', 'Reads ''our ball, live'': our man on it, or loose in play after our touch, no restart pending - the gate for the build-up jog, line runs and walking.', 'unnamed', NULL, NULL, 'read-who-has-the-ball', 'high', true),
  ('recv_track_rolling_ball', 'game/src/ai/Brain.cpp', 833, 'G5.58 §8.159', 'individual', 'Meeting a rolling ball within track_m (3 m) he runs with the ball''s own velocity and closes the gap on top, instead of braking to a meet point that keeps rolling on.', 'concept', (SELECT id FROM game_concepts WHERE name = 'meet-the-pass'), NULL, NULL, 'medium', false),
  ('race_arrive_on_time', 'game/src/ai/Brain.cpp', 1122, 'G4.84; G4.80', 'individual', 'Racing to a moving ball he runs at least fast enough to be at the meet point when the ball is (distance / read time +10%), and otherwise no faster than he can still stop from, arriving through it at 3 m/s.', 'concept', (SELECT id FROM game_concepts WHERE name = 'meet-the-pass'), NULL, NULL, 'medium', false),
  ('wingback_ball_side_goes_far_tucks', 'game/src/ai/Brain.cpp', 233, 'G5.36 §8.134', 'group', 'Without the ball the wing-back on the ball''s side stands at a wide man''s depth and the far one drops to a full-back''s depth, tucked to a back four''s width; with the ball both are wide men.', 'concept', (SELECT id FROM game_concepts WHERE name = 'balance'), 'asymmetric-fullbacks', NULL, 'medium', false),
  ('poss_width_by_ball', 'game/src/ai/Brain.cpp', 267, 'G5.102 §8.204; G5.120 §8.221', 'team', 'With our ball each role holds its formation width scaled to the real in-possession gap for the ball''s band, and slides across by role with the ball''s side.', 'concept', (SELECT id FROM game_concepts WHERE name = 'width'), 'optimal-spacing', NULL, 'medium', false),
  ('read_ball_destination', 'game/src/ai/Brain.cpp', 253, 'G5.30 §8.128', 'individual', 'Reads where a free ball is going: the point where the first man of either side on the race read takes it (else the ball itself).', 'unnamed', NULL, 'intercept', 'read-where-the-ball-is-going', 'medium', true),
  ('pass_first_time_when_pressed', 'game/src/ai/Brain.cpp', 757, 'G4.95b', 'individual', 'Still in his control touch with an opponent within 2.5 m, a ground pass to a mate goes first time (the lay-off, the wall pass back).', 'unnamed', NULL, 'lay-off, wall-pass', 'one-touch-when-pressed', 'medium', false),
  ('pass_lead_into_path', 'game/src/ai/Brain.cpp', 774, 'G4.81; G4.82', 'individual', 'A ground pass at a mate''s feet is aimed where he will be when it arrives (at most 10 m on) and weighted to that spot; if the led ball reads unsafe he plays the ball he checked.', 'unnamed', NULL, 'release-timing', 'pass-into-his-path', 'medium', false),
  ('pass_keep_carry_feet', 'game/src/ai/Brain.cpp', 811, 'G5.127 §8.228', 'individual', 'Leading a pass, the man on the ball keeps his carry direction to the release - the re-aim moves the kick, not his feet (before, he walked at the man he would pass to).', 'fudge', NULL, NULL, NULL, 'low', false),
  ('read_loft_lead', 'game/src/ai/Reads.cpp', 62, 'G4.48; G5.155', 'individual', 'Works out where to drop a lofted pass for a moving mate (his position plus his velocity times the flight time) and the carry that drops it there, capped by his kick range.', 'unnamed', NULL, 'over-top', 'drop-it-into-his-run', 'low', true),
  ('restart_taker', 'game/src/ai/Brain.cpp', 369, 'G5.2', 'team', 'Who takes our held restart: the keeper for a goal kick, the man a restart shape puts on the spot, else our nearest outfielder to it; a kick-off or free kick, our nearest man to the ball (DefendingBlock.cpp:305).', 'unnamed', NULL, 'nearest-decides', 'restart-taker', 'medium', false),
  ('restart_walk_to_spot', 'game/src/ai/Brain.cpp', 416, 'G5.2', 'individual', 'The taker walks to the dead ball - behind the line for a throw, behind the ball for a corner - and steps onto it once the referee has it ready.', 'unnamed', NULL, NULL, 'set-the-restart', 'medium', false),
  ('restart_shape_hold', 'game/src/ai/Brain.cpp', 319, 'G4.58; G5.2', 'team', 'While a side''s dead ball waits, each man in a supplied restart shape holds his mark facing the ball until it is played.', 'unnamed', NULL, NULL, 'restart-shape', 'medium', false),
  ('keeper_goal_kick_long_fallback', 'game/src/ai/Brain.cpp', 401, 'G5.2', 'keeper', 'The keeper takes his goal kick with his own on-ball choice; if nothing is on after keeper_wait_s (3 s) he launches it 55 m straight upfield.', 'concept', (SELECT id FROM game_concepts WHERE name = 'direct-ball'), NULL, NULL, 'low', false),
  ('throw_in_to_free_man', 'game/src/ai/Brain.cpp', 434, 'G5.2', 'individual', 'The thrower looks for 1 s, then throws to the mate in range (4 m to the throw''s reach) with the most space plus ground gained, marked down if the throw reads unsafe; he waits up to 4 s for a man 3 m free, then throws it down the line.', 'concept', (SELECT id FROM game_concepts WHERE name = 'throw-in-retain'), NULL, NULL, 'medium', false),
  ('corner_delivery', 'game/src/ai/Brain.cpp', 551, 'G5.2', 'individual', 'The corner taker looks for 1.5 s, then lofts it to our freest mate 3-14 m off their line within 12 m of the middle (nobody there: 11 m out, central).', 'unnamed', NULL, 'corner-blockers', 'corner-delivery-to-the-free-man', 'medium', false),
  ('fk_into_box', 'game/src/ai/Brain.cpp', 563, 'G5.182 §8.288; G5.183', 'individual', 'A free kick is delivered into the box like a corner at the real share for its spot (one roll per free kick, by distance band and inside/wide); otherwise the taker''s open-play choice plays it.', 'unnamed', NULL, NULL, 'free-kick-into-the-box', 'high', false),
  ('fk_stand_over_ball', 'game/src/ai/Brain.cpp', 355, 'G5.184 §8.290', 'individual', 'The free-kick taker stands still over the ball until he releases it, because the kick is live at his first touch and his on-ball state carried it 10 m before striking.', 'fudge', NULL, NULL, NULL, 'medium', false),
  ('sp_corner_attack_shape', 'game/src/ai/Brain.cpp', 640, 'G5.183 §8.289', 'team', 'Waiting for our corner, six attackers take fixed spots: five in the box (near post, six-yard edge, penalty spot, far side, 13 m) and one at the edge 20 m out; each spot takes the nearest free outfielder, once a restart.', 'unnamed', NULL, 'corner-ring, second-phase-corner, box-occupancy', 'corner-attacking-shape', 'low', false),
  ('sp_corner_defend_shape', 'game/src/ai/Brain.cpp', 640, 'G5.183 §8.289', 'team', 'Defending a corner: three men zonal across the six-yard box, five goal-side (1 m) of each attacker''s spot in the box, and one out toward the ball side at 9 m.', 'unnamed', NULL, 'defend-the-cross, marking', 'corner-defending-shape', 'medium', false),
  ('sp_fk_wall', 'game/src/ai/Brain.cpp', 650, 'G5.183 §8.289; G5.184 §8.290', 'group', 'Defending a free kick 18-52 m out bound for the box (or central within 25 m): a wall on the ball''s line to the goal''s middle, 9.15 m off the ball - three men inside 35 m, one beyond.', 'unnamed', NULL, NULL, 'free-kick-wall', 'high', false),
  ('sp_fk_box_lines', 'game/src/ai/Brain.cpp', 660, 'G5.183 §8.289', 'team', 'At that free kick the attackers form a line of four across the box (12.5 m out inside 35 m, else 17.5 m) plus two more, and the defenders a line half a metre goal-side of it plus one or two deeper.', 'unnamed', NULL, 'line-hold', 'free-kick-box-line', 'medium', false),
  ('penalty_kick', 'game/src/ai/Brain.cpp', 487, 'G5.40 Law 14', 'individual', 'The penalty taker waits 1.5 s, then shoots at a spot drawn from where real penalties went (side, distance from centre, height; 6.6% wide or over).', 'unnamed', NULL, 'placement', 'penalty-kick', 'medium', false),
  ('penalty_stay_out', 'game/src/ai/Brain.cpp', 523, 'G5.40 Law 14', 'team', 'Until the penalty is kicked every outfielder but the taker stays outside the area and the arc, behind a line about 21 m out.', 'unnamed', NULL, NULL, 'law-14-outside-the-area', 'high', false),
  ('keeper_penalty_on_line', 'game/src/ai/Brain.cpp', 528, 'G5.40 Law 14', 'keeper', 'The defending keeper stands on his line at the middle of the goal facing the taker until the penalty is struck.', 'unnamed', NULL, NULL, 'keeper-on-his-line-at-a-penalty', 'high', false),
  ('law_distance_at_restart', 'game/src/ai/Brain.cpp', 707, 'G5.2 Laws 13/15/17; §8.250 Law 8', 'team', 'At their dead ball each of ours stops at, or backs off to, the Law''s distance: 2 m from a throw, 9.15 m from a corner or free kick, 4 m from a drop ball.', 'unnamed', NULL, NULL, 'law-distance-at-restarts', 'high', false),
  ('law_out_of_their_box_goal_kick', 'game/src/ai/Brain.cpp', 735, 'Law 16', 'team', 'At their goal kick every one of ours stays outside, or walks out of, their penalty area until it is kicked - the marker picks his centre-back up on the 18.', 'unnamed', NULL, NULL, 'law-16-outside-their-box', 'high', false),
  ('keeper_goes_for_loose_ball', 'game/src/ai/Players.cpp', 55, NULL, 'keeper', 'The keeper becomes his team''s loose-ball man when the race read has him first (the read counts him only for a ball inside his own box, Reads.cpp:217) or the pass back is his - he goes and takes it.', 'concept', (SELECT id FROM game_concepts WHERE name = 'command-box'), 'keeper-extra-player', NULL, 'medium', false),
  ('pick_one_job_per_man', 'game/src/ai/Players.cpp', 50, 'G5.22 §8.120; G5.72', 'individual', 'Each tick every man gets exactly one job in a fixed order: on the ball; his team''s loose-ball man; the receiver of our pass; keeper position; then in a defending phase (block, defensive transition, their set piece alike) presser, else marker, else block spot; otherwise the in-possession states. No job that acts = hold the block spot (Brain.cpp:336).', 'unnamed', NULL, 'nearest-decides', 'one-job-per-man', 'medium', false),
  ('read_possession_side', 'game/src/ai/TeamPhase.cpp', 6, 'G5.21 §8.119', 'team', 'Reads which side has the ball: the man on it; a loose ball in play stays with the side that touched it last; a dead ball with the side taking it; over the line with the call to come, unknown.', 'unnamed', NULL, NULL, 'read-who-has-the-ball', 'high', true),
  ('read_phase', 'game/src/ai/TeamPhase.cpp', 41, 'G5.21 §8.119', 'team', 'Reads the team''s phase of play each tick: in possession, attacking transition, defending block, defensive transition, our set piece, their set piece; back in play from a set piece goes straight to the settled phase.', 'unnamed', NULL, NULL, 'read-phase-of-play', 'high', true),
  ('read_def_transition', 'game/src/ai/TeamPhase.cpp', 62, 'G5.21 §8.119', 'team', 'A change of side to them starts ''defensive transition'' for transition_s (6 s, the six-second rule) before settling to the defending block; in the files audited the defending code treats it exactly as the settled block.', 'unnamed', NULL, 'counter-press, zero-pause-switch', 'read-we-just-lost-it', 'medium', true),
  ('read_att_transition', 'game/src/ai/TeamPhase.cpp', 62, 'G5.21 §8.119', 'team', 'A change of side to us starts ''attacking transition'' for transition_s (6 s) before settling to in possession.', 'unnamed', NULL, 'counter-attack, counter-or-keep', 'read-we-just-won-it', 'medium', true),
  ('phase_min_dwell', 'game/src/ai/TeamPhase.cpp', 58, 'G5.21 §8.119', 'team', 'A change of side only counts once it has held min_dwell_s (0.3 s), so a ricochet between two men does not flip both shapes for a tick.', 'fudge', NULL, NULL, NULL, 'medium', false),
  ('read_race', 'game/src/ai/Reads.cpp', 132, 'G4.49; G4.86; G4.85; G5.165 §8.271', 'individual', 'Reads who gets to a free ball first and where: the ball''s own path tick by tick, each man starting after his reaction and perception delay, his run plus his reach; each team''s first man.', 'unnamed', NULL, 'nearest-decides, second-ball', 'read-the-race', 'medium', true),
  ('read_header_point', 'game/src/ai/Reads.cpp', 196, 'G5.11 §8.108', 'individual', 'An outfielder also reads the head-height point of a dropping ball as a place he can take it, so he goes to head a cross instead of to where it lands (off unless physics.receive.read_header and an aerial radius are set).', 'unnamed', NULL, 'defend-the-cross, win-duel', 'read-the-header', 'medium', true),
  ('read_own_touch_pace', 'game/src/ai/Reads.cpp', 207, 'G4.85', 'individual', 'On his own side''s ball a man reads the take point as where the ball has slowed to a pace his first touch can hold, not the earliest point he can touch it.', 'unnamed', NULL, 'first-touch-direction', 'take-it-where-you-can-control-it', 'medium', true),
  ('read_offside_leave_it', 'game/src/ai/Reads.cpp', 193, NULL, 'individual', 'A man flagged in an offside position is left out of the race for the ball - he leaves it.', 'unnamed', NULL, 'stay-onside', 'leave-it-when-offside', 'medium', true),
  ('read_get_in_line', 'game/src/ai/Reads.cpp', 245, 'G5.5; G5.98 §8.199', 'individual', 'The receiver of a rolling pass reads the spot on its line his body can be on: onto the line first (the foot of his perpendicular), then along it, 0.25 s early where there is time, on time when the ball is under 0.5 s away, and only where it has slowed to his control pace.', 'concept', (SELECT id FROM game_concepts WHERE name = 'meet-the-pass'), NULL, NULL, 'high', true),
  ('read_pass_safe', 'game/src/ai/Reads.cpp', 297, 'G4.19; G4.86; G5.155; G5.156', 'individual', 'Before striking a ground or lofted pass the passer reads the same race on the ball he is about to hit: safe only if a mate takes it before any opponent (opponents given extra reach).', 'unnamed', NULL, 'safe-pass, open-closed-ball', 'read-pass-safety', 'low', true),
  ('read_chance_quality', 'game/src/ai/Reads.cpp', 37, 'G4.21', 'individual', 'Reads a shooting chance as the goal-mouth angle at the shooter, halved for each outfield opponent standing inside the shooter-post-post triangle.', 'unnamed', NULL, 'shot-selection', 'read-chance-quality', 'medium', true),
  ('form_base_shape', 'game/src/ai/Formation.cpp', 38, '§8.3', 'team', 'The fallback line-up when no formation comes from the DB: a built-in 4-4-2 (or 1-1-1 / rows of four) of normalised base positions; a role is read from the slot''s role name, else its shirt number (Players.cpp:11).', 'unnamed', NULL, 'optimal-spacing', 'formation-base-shape', 'low', false),
  ('form_anchor_slide', 'game/src/ai/Formation.cpp', 78, '[HELIOS]-lite §8.3', 'team', 'anchorFor: the whole shape translates toward the ball by 25% / 30% of its position, capped at 14 m / 10 m. No caller left in game/src - superseded by the block spot and slideY.', 'concept', (SELECT id FROM game_concepts WHERE name = 'block-slide'), NULL, NULL, 'low', false),
  ('keeper_leash', 'game/src/ai/Formation.cpp', 89, '§8.3', 'keeper', 'anchorFor: the keeper stays within 8 m of his goal line and 6 m of its centre whatever the shape''s slide. No caller left in game/src.', 'fudge', NULL, NULL, NULL, 'low', false),
  ('poss_shot_policy', 'game/src/ai/Possession.cpp', 244, 'G5.23', 'individual', 'Carrier within 35 m of goal shoots at the real share of releases for his distance x goal-mouth angle, one roll a spell, checked before any pass.', 'concept', (SELECT id FROM game_concepts WHERE name = 'shot-selection'), NULL, NULL, 'high', false),
  ('poss_shot_crowd', 'game/src/ai/Possession.cpp', 258, 'G5.198 §8.304', 'individual', 'Carrier shoots less (or more) often according to how many of their outfielders stand nearer the goal centre than he does (off unless shot.crowd row on).', 'concept', (SELECT id FROM game_concepts WHERE name = 'shot-selection'), NULL, NULL, 'medium', false),
  ('poss_shot_aim', 'game/src/ai/Possession.cpp', 266, 'G5.37 §8.135', 'individual', 'The shot''s aim point (across the goal and height, incl. wide/over) is drawn from where real shots from that distance crossed the line; side of goal 50/50.', 'concept', (SELECT id FROM game_concepts WHERE name = 'placement'), NULL, NULL, 'low', false),
  ('poss_keeper_long_ball', 'game/src/ai/Possession.cpp', 305, 'G5.144 §8.248', 'keeper', 'Keeper on the ball goes long at the real share (goal kick 77%, open play 40% roll): lofted to a mate 50-75 m upfield, else 60 m straight upfield.', 'concept', (SELECT id FROM game_concepts WHERE name = 'direct-ball'), NULL, NULL, 'medium', false),
  ('poss_clear_danger', 'game/src/ai/Possession.cpp', 333, 'G5.139 §8.243', 'individual', 'Outfielder on the ball boots it clear first time at the real rate for where he is (own box / own third / midfield / their third) and how close the nearest opponent is.', 'concept', (SELECT id FROM game_concepts WHERE name = 'clear-the-danger'), NULL, NULL, 'high', false),
  ('poss_clear_aim', 'game/src/ai/Possession.cpp', 348, 'G5.139 §8.243', 'individual', 'A clearance is aimed a drawn length upfield toward the side with fewer of theirs, or straight up his touchline when he is 24 m+ wide (if in doubt put it out).', 'unnamed', NULL, 'clear-the-danger', 'clear-upfield-to-the-empty-side', 'medium', false),
  ('poss_clear_out_of_play', 'game/src/ai/Possession.cpp', 358, 'G5.188 §8.294', 'individual', 'A clearance is put behind for a corner or over the touchline for a throw at the real share for his spot, else upfield infield (off unless clear_out row on).', 'unnamed', NULL, 'clear-the-danger', 'clear-out-of-play', 'medium', false),
  ('poss_pass_zone_policy', 'game/src/ai/Possession.cpp', 380, 'G5.25 / G5.59 §8.160', 'individual', 'Carrier picks his pass by one weighted roll a spell: each mate weighted by the real share of passes from the ball''s zone to the mate''s zone (x kappa when the zone is held).', 'unnamed', NULL, 'pass-ladder', 'pass-choice-by-zone-share', 'medium', false),
  ('poss_pass_near_mate', 'game/src/ai/Possession.cpp', 387, 'G5.74 §8.175 / §8.236', 'individual', 'Within a zone and overall the nearer mate is preferred (e^-d/lambda split, plus a lift by pass length band that favours 0-10 m passes).', 'concept', (SELECT id FROM game_concepts WHERE name = 'short-simple'), NULL, NULL, 'medium', false),
  ('poss_pass_far_wing', 'game/src/ai/Possession.cpp', 393, 'G5.172 §8.278', 'individual', 'Of the passes into a wide zone, a real share goes to the mate on the far wing (the other side from the ball), more from the centre than from wide.', 'concept', (SELECT id FROM game_concepts WHERE name = 'switch-play'), NULL, NULL, 'medium', false),
  ('poss_pass_free_man', 'game/src/ai/Possession.cpp', 412, 'G5.83 §8.184 / G5.157 §8.262', 'individual', 'A mate with an opponent close gets less of the pass share by the marker''s distance; a high pass minds the marker much less than a flat one.', 'unnamed', NULL, 'safe-pass', 'find-the-free-man', 'high', false),
  ('poss_pass_back_to_keeper', 'game/src/ai/Possession.cpp', 400, 'G5.76 §8.177', 'individual', 'Carrier plays back to his own keeper at the real share for his distance off his own goal (keeper kept out of the zone split; share applied at :744).', 'concept', (SELECT id FROM game_concepts WHERE name = 'keeper-extra-player'), NULL, NULL, 'medium', false),
  ('poss_pass_min_length', 'game/src/ai/Possession.cpp', 459, NULL, 'individual', 'No pass (to feet, in behind or into space) is considered to a target under pass_min_m (5 m) away.', 'fudge', NULL, NULL, NULL, 'medium', false),
  ('poss_pass_short_direction', 'game/src/ai/Possession.cpp', 468, 'G5.145 §8.249', 'individual', 'A pass under 20 m is weighted by its direction (forward / lateral / back) for his band off their line; real passers play it square or back half as often (rows default 1 = off).', 'concept', (SELECT id FROM game_concepts WHERE name = 'verticality'), NULL, NULL, 'medium', false),
  ('poss_pass_to_mover', 'game/src/ai/Possession.cpp', 474, '§8.237', 'individual', 'A mate is weighted by his running speed so the man on the move is found more than the man standing still (rows default 1 = off).', 'unnamed', NULL, 'release-timing', 'pass-to-the-man-on-the-move', 'medium', false),
  ('poss_pass_risk_gate', 'game/src/ai/Possession.cpp', 495, 'G5.25 / G5.73 §8.174', 'individual', 'A pass the race read says they would cut out is still offered but only at risk_weight (0.25) of its share, a high one at high_risk (0.6); safe passes keep full weight.', 'concept', (SELECT id FROM game_concepts WHERE name = 'safe-pass'), NULL, NULL, 'medium', false),
  ('poss_pass_risk_own_third', 'game/src/ai/Possession.cpp', 426, 'G5.202 §8.308', 'individual', 'In our own third a risky pass is offered at the lower risk_own3 weight instead (no risks at the back; 0 = same as elsewhere).', 'concept', (SELECT id FROM game_concepts WHERE name = 'risk-by-third'), NULL, NULL, 'high', false),
  ('poss_pass_high_or_ground', 'game/src/ai/Possession.cpp', 488, 'G5.73 §8.174 / G5.75 §8.176 / G5.235 §8.341', 'individual', 'A pass to feet goes high or along the ground at the real share for its length, its direction (forward / lateral / back or five angle bands) and his third; never high past his kicking range.', 'unnamed', NULL, 'direct-ball', 'pass-height-choice', 'high', false),
  ('poss_long_ball_beyond', 'game/src/ai/Possession.cpp', 508, 'G5.212 §8.318', 'individual', 'A 30 m+ high ball from our own third is aimed beyond the target man toward their goal by real offsets, not onto him (long_beyond 0 = off).', 'unnamed', NULL, 'target-and-runner', 'long-ball-beyond-the-target', 'medium', false),
  ('poss_long_ball_own_side', 'game/src/ai/Possession.cpp', 531, 'G5.214 §8.320', 'individual', 'A 30 m+ high ball from our own third is weighted to go down the kicker''s own wing or channel rather than across the pitch (rows default 1 = off).', 'unnamed', NULL, 'direct-ball', 'long-ball-down-his-own-side', 'medium', false),
  ('poss_pass_chip_blocked_lane', 'game/src/ai/Possession.cpp', 544, 'G5.25', 'individual', 'For a pass into their box from outside (and all passes when the high table is off): on the ground if the lane is safe, else lofted if the loft is safe, else tried at risk weight.', 'unnamed', NULL, 'over-top', 'chip-over-the-blocked-lane', 'medium', false),
  ('poss_behind_choose', 'game/src/ai/Possession.cpp', 481, 'G5.27', 'individual', 'For a mate 0-18 m short of their offside line, a real share of his passes (50% at 0-2 m gap down to 2%) is played in behind him instead of to feet.', 'concept', (SELECT id FROM game_concepts WHERE name = 'beat-the-high-line'), 'over-top', NULL, 'medium', false),
  ('poss_behind_spot_and_weight', 'game/src/ai/Possession.cpp', 567, 'G5.27', 'individual', 'The ball in behind is aimed a rolled 2.6-9.7 m past their line on the runner''s line of run, and a ground one is struck to arrive as his run does.', 'unnamed', NULL, 'release-timing', 'weight-the-through-ball', 'medium', false),
  ('poss_behind_to_runner', 'game/src/ai/Possession.cpp', 599, 'G5.91 §8.192', 'individual', 'The ball in behind is weighted to the man already running at their goal (x0.42 if moving back, x2.95 at 6+ m/s forward).', 'unnamed', NULL, 'runs', 'play-in-the-running-man', 'medium', false),
  ('poss_behind_air_or_ground', 'game/src/ai/Possession.cpp', 604, 'G5.161 §8.266 / G5.51 §8.152', 'individual', 'A ball in behind goes in the air at the real share (58%) or on the ground, and is still played as a 50/50 when the race read says they win it.', 'concept', (SELECT id FROM game_concepts WHERE name = 'over-top'), NULL, NULL, 'medium', false),
  ('poss_space_empty_zone', 'game/src/ai/Possession.cpp', 622, 'G5.54 §8.155 / G5.57', 'individual', 'A zone ahead with no mate in it keeps its real pass share: the carrier plays the ball into that space (zone middle, wide channel) for the mate who gets there first.', 'unnamed', NULL, 'over-top', 'ball-into-space', 'high', false),
  ('poss_space_lead_runner', 'game/src/ai/Possession.cpp', 641, 'G5.195 §8.301', 'individual', 'With space_lead_s on, the ball into space is aimed ahead of a runner on his line, at the spot he beats their men to by most, not the zone middle (default off).', 'unnamed', NULL, 'release-timing', 'lead-the-runner', 'medium', false),
  ('poss_space_race_gate', 'game/src/ai/Possession.cpp', 670, 'G5.55 §8.156 / G5.58 §8.159 / G5.194 §8.300', 'individual', 'A ground ball into space is played only if a mate reaches it within 4.5 s and before any of theirs (or at space_risk when contested), and never to a mate already past the spot.', 'unnamed', NULL, 'safe-pass', 'ball-into-space-only-if-we-win-the-race', 'medium', false),
  ('poss_space_high', 'game/src/ai/Possession.cpp', 701, 'G5.230 §8.336', 'individual', 'The ball into an empty zone goes in the air at the real high share for its length and direction and is played whoever is first (space.high 0 = off).', 'unnamed', NULL, 'direct-ball', 'long-ball-into-space', 'medium', false),
  ('poss_space_die_at_weight', 'game/src/ai/Possession.cpp', 725, 'G5.57 §8.158', 'individual', 'A ground ball into space is weighted to reach the spot as the runner does and die no more than 2 m past it.', 'unnamed', NULL, 'release-timing', 'weight-of-pass', 'medium', false),
  ('poss_cross_to_space', 'game/src/ai/Possession.cpp', 636, 'G5.54 §8.155', 'individual', 'From wide, with nobody in their box zone, he crosses in the air to a spot 7.5 m out in the middle, struck whoever gets there first.', 'unnamed', NULL, 'cut-back', 'cross-into-the-box', 'high', false),
  ('poss_cross_to_man', 'game/src/ai/Possession.cpp', 782, 'G5.25', 'individual', 'A pass to a mate in their box from outside it goes in the air at the real cross share for the origin zone, if the loft is safe.', 'unnamed', NULL, 'cut-back', 'cross-into-the-box', 'high', false),
  ('poss_keeper_punt_nothing_on', 'game/src/ai/Possession.cpp', 813, NULL, 'keeper', 'Keeper with no pass candidate at all kicks it 55 m straight upfield.', 'concept', (SELECT id FROM game_concepts WHERE name = 'direct-ball'), NULL, NULL, 'medium', false),
  ('poss_clear_nothing_on', 'game/src/ai/Possession.cpp', 814, NULL, 'individual', 'Outfielder within 25 m of his own line with no pass candidate lofts it 45 m straight upfield.', 'concept', (SELECT id FROM game_concepts WHERE name = 'clear-the-danger'), NULL, NULL, 'medium', false),
  ('poss_keep_and_carry_nothing_on', 'game/src/ai/Possession.cpp', 823, NULL, 'individual', 'With no shot, clearance or pass candidate he keeps the ball and carries it on his carry line.', 'concept', (SELECT id FROM game_concepts WHERE name = 'keep-it-under-pressure'), NULL, NULL, 'low', false),
  ('poss_carry_until_release', 'game/src/ai/Possession.cpp', 771, 'G5.29', 'individual', 'Whatever pass he has chosen, he carries the ball on his carry line until the World releases the kick (his real time on the ball); the kick goes at its aim, not the way he runs.', 'unnamed', NULL, 'pausa', 'carry-while-the-pass-develops', 'medium', false),
  ('poss_carry_free_line', 'game/src/ai/Possession.cpp', 162, 'G5.128 §8.229', 'individual', 'Unpressed (nobody within 3 m), his carry direction is one draw a spell from the real free-carry lines for his zone (at goal 11-19%, across or back 18-41%), inward or outward.', 'unnamed', NULL, 'drive-into-space', 'carry-line-by-zone', 'medium', false),
  ('poss_carry_pressed_line', 'game/src/ai/Possession.cpp', 154, 'G5.130 §8.231', 'individual', 'With an opponent within 5 m his carry direction is drawn from the real under-pressure carry lines for his zone (less at goal, more across or back).', 'unnamed', NULL, 'keep-it-under-pressure', 'carry-under-pressure', 'medium', false),
  ('poss_carry_off_nearest_man', 'game/src/ai/Possession.cpp', 184, 'G5.29', 'individual', 'With an opponent within 4 m his carry line is bent away from that man (0.7 x the away vector added).', 'unnamed', NULL, 'shield-ball', 'carry-away-from-pressure', 'medium', false),
  ('poss_pressed_touch_cone', 'game/src/ai/Possession.cpp', 188, 'G5.81 §8.182', 'individual', 'Pressed inside 3 m, he takes the ball away from the man 59%, across him 27%, toward him 14% (one draw a spell); the first touch plays the ball that way.', 'concept', (SELECT id FROM game_concepts WHERE name = 'first-touch-direction'), 'shield-ball', NULL, 'medium', false),
  ('poss_carry_line_latch', 'game/src/ai/Possession.cpp', 157, 'G5.132 §8.233', 'individual', 'The carry line''s zone and pressure state are frozen at the spell''s first call so the drawn line does not swing 45+ deg each second.', 'fudge', NULL, NULL, NULL, 'medium', false),
  ('poss_carry_edge_turn', 'game/src/ai/Possession.cpp', 212, 'G5.141 §8.245 / G5.193 §8.299', 'individual', 'Within 3 m of a touchline or their goal line (and his own goal line when edge_own) any carry direction heading out is mirrored back infield.', 'unnamed', NULL, 'shield-ball', 'keep-the-ball-in-play', 'low', false),
  ('poss_shape_depth_by_ball', 'game/src/ai/Possession.cpp', 1806, 'G5.22 §8.120 / G5.43 §8.143', 'team', 'Each supporting player holds his role''s real mean depth off THEIR goal line for the ball''s 10 m band (CB deepest, ST highest).', 'unnamed', NULL, 'support, optimal-spacing', 'possession-shape-by-ball-depth', 'medium', false),
  ('poss_width_by_ball_band', 'game/src/ai/Possession.cpp', 35, 'G5.102 §8.204 / G5.121 §8.222', 'team', 'A role pair''s width across is scaled by the ball''s band: centre-backs split 12 m to 21 m as the ball goes back into our half, wide men 22 m to 32 m (table here; applied where across_ours is built).', 'concept', (SELECT id FROM game_concepts WHERE name = 'cb-split'), 'width', NULL, 'medium', false),
  ('poss_slide_to_ball_side', 'game/src/ai/Possession.cpp', 1381, 'G5.120 §8.221', 'team', 'Each role''s spot slides toward the ball''s side by a real amount for the ball''s distance off the centre line (table + slideAt here; applied outside this file).', 'unnamed', NULL, 'block-slide', 'shift-to-the-ball-side-in-possession', 'medium', false),
  ('poss_slide_ramp', 'game/src/ai/Possession.cpp', 1383, '§8.238', 'team', 'The slide is ramped to 0 inside 2 m of the centre line so spots do not jump 1-2 m each time the ball crosses the middle.', 'fudge', NULL, NULL, NULL, 'high', false),
  ('poss_spell_depth_offset', 'game/src/ai/Possession.cpp', 1793, 'G5.46', 'individual', 'Each man takes his own depth offset from his role''s spot for the whole possession, one roll a spell through the real p10-p90 (sd 4-9 m by role).', 'unnamed', NULL, 'staggered-shape', 'own-depth-for-the-spell', 'low', false),
  ('poss_follow_dropping_line', 'game/src/ai/Possession.cpp', 1810, 'G5.62 §8.163', 'individual', 'When their back line sits deeper than usual for this ball, a man near that line goes forward with it by the difference; men 10 m+ behind it do not.', 'unnamed', NULL, 'pin-the-fullback', 'follow-their-line-as-it-drops', 'medium', false),
  ('poss_hold_touchline', 'game/src/ai/Possession.cpp', 1835, 'G5.168 §8.274 / G5.170 §8.276 / G5.171 §8.277', 'individual', 'A FB, DM/CM or wide man holds his touchline (0-4.5 m off it) for the spell at the real share for the ball''s band, near or far side, rising as the spell settles; once out he stays out, except in their last 35 m.', 'concept', (SELECT id FROM game_concepts WHERE name = 'width'), 'hold-width-weak-side', NULL, 'high', false),
  ('poss_fullback_high_and_wide', 'game/src/ai/Possession.cpp', 1854, 'G5.174 §8.280', 'individual', 'A full-back on his touchline stands at the real offset ahead of the ball (up to 20 m ahead while the centre-backs build in our half), never past their offside line.', 'unnamed', NULL, 'width, overlap', 'fullback-high-and-wide', 'medium', false),
  ('poss_striker_pulls_wide_deep_ball', 'game/src/ai/Possession.cpp', 1870, 'G5.216 §8.322', 'individual', 'With the ball deep and wide in our end the striker may pull out to that wing 57.5 m off their line as the target of the long ball down the side (roll default 0 = off).', 'unnamed', NULL, 'target-and-runner, outlet', 'striker-pulls-wide-as-the-target', 'medium', false),
  ('poss_st_am_channel_drift', 'game/src/ai/Possession.cpp', 1883, 'G5.89 §8.190', 'individual', 'With the ball 35-70 m out the striker or AM drifts into their wide channel on the ball''s side at the real share, one roll a man a spell a zone.', 'unnamed', NULL, 'find-the-pocket', 'drift-into-the-wide-channel', 'medium', false),
  ('poss_wing_support', 'game/src/ai/Possession.cpp', 1900, 'G5.125 §8.226', 'group', 'Ball wide 18-52 m off their line: the DM/CM, AM, wide man or ST on that side goes to a spot 7-9 m off the ball (ahead / inside by role) to support the man on it.', 'concept', (SELECT id FROM game_concepts WHERE name = 'support'), NULL, NULL, 'high', false),
  ('poss_lone_man_side', 'game/src/ai/Possession.cpp', 1922, 'G5.120 §8.221', 'individual', 'A lone DM, AM or ST stands off the centre line on one side for the spell, more often the ball''s side as the ball goes wide.', 'unnamed', NULL, 'find-the-pocket, staggered-shape', 'lone-man-picks-a-side', 'medium', false),
  ('poss_spread_off_mates', 'game/src/ai/Possession.cpp', 855, 'G5.118 §8.219', 'group', 'A supporting man''s spot is pushed away from any outfield mate within 12 m of it (up to 6 m) so men do not bunch.', 'unnamed', NULL, 'optimal-spacing', 'keep-your-distance-from-mates', 'low', false),
  ('poss_stay_onside', 'game/src/ai/Possession.cpp', 840, 'G5.22 (Law 11)', 'individual', 'Support, box-run and line-run spots are never further on than their second-last man (or the ball, or halfway) less a 0.5 m margin (also :1016, :1049).', 'concept', (SELECT id FROM game_concepts WHERE name = 'stay-onside'), NULL, NULL, 'high', false),
  ('poss_front_men_on_line', 'game/src/ai/Possession.cpp', 1311, 'G5.47 / G5.49', 'group', 'Our most advanced free outfielder stands on their offside line a rolled 0.5-4.8 m short of it, and the second man 1.2-9.9 m short, each for a tenure (spot applied at :879).', 'unnamed', NULL, 'stay-onside, pin-the-fullback', 'play-on-the-last-defender', 'medium', false),
  ('poss_front_job_hysteresis', 'game/src/ai/Possession.cpp', 1335, 'G5.63 §8.164', 'group', 'The front-man job stays with a momentarily busy holder and only changes hands when a mate is front_swap_m (1 m) further on, so it does not flip between men.', 'fudge', NULL, NULL, NULL, 'medium', false),
  ('poss_front_close_cap', 'game/src/ai/Possession.hpp', 227, 'G5.50', 'individual', 'A cap (1 m/s over the line''s own speed) on how fast a front man closes on his line spot, fitted to the real count of ball-still runs (declared here; applied outside this file).', 'fudge', NULL, NULL, NULL, 'medium', false),
  ('poss_receive_meet_pass', 'game/src/ai/Possession.cpp', 894, 'G5.5', 'individual', 'The man a pass is for moves into line with it (else to the race spot) and faces the ball.', 'concept', (SELECT id FROM game_concepts WHERE name = 'meet-the-pass'), NULL, NULL, 'high', false),
