  ('keeper_set_position', 'game/src/ai/Possession.cpp', 938, 'G5.22', 'keeper', 'Keeper without the ball stands on the ball-to-goal-centre line, 1 m out plus 8% of the ball''s distance, up to 12 m, facing the ball.', 'concept', (SELECT id FROM game_concepts WHERE name = 'narrow-angle'), NULL, NULL, 'medium', false),
  ('keeper_depth_by_cover', 'game/src/ai/Possession.cpp', 943, 'G5.122 §8.223', 'keeper', 'Their ball within 25 m of our goal: he comes off his line by its distance and how few of ours are goal-side (4.8 m when the man is through, 2 m behind a crowd).', 'concept', (SELECT id FROM game_concepts WHERE name = 'narrow-angle'), NULL, NULL, 'high', false),
  ('keeper_reaction_hold', 'game/src/ai/Possession.cpp', 960, 'G5.37 §8.135', 'keeper', 'For his reaction time after their strike he carries on as he was moving: no new line, no dive.', 'unnamed', NULL, 'narrow-angle', 'keeper-reaction-time', 'medium', false),
  ('keeper_dive', 'game/src/ai/Possession.cpp', 974, 'G5.22', 'keeper', 'A shot crossing his line within 1.2 s inside the posts (+1 m) that he cannot run to: he dives at the crossing point.', 'unnamed', NULL, 'narrow-angle', 'keeper-dive-save', 'high', false),
